"use client";

import { useState, useRef, useEffect } from "react";
import { 
  Send, UploadCloud, FileText, Leaf, Loader2, Info, 
  MessageSquare, Bot, User, CheckCircle2, Sparkles, 
  ChevronRight, LayoutDashboard, Settings, HelpCircle
} from "lucide-react";

type Message = {
  role: "user" | "bot";
  content: string;
};

export default function Home() {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadedFileName, setUploadedFileName] = useState<string | null>(null);
  const [chatMode, setChatMode] = useState<"simple" | "pdf">("simple");
  
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const formData = new FormData();
    formData.append("file", file);

    try {
      const res = await fetch("http://127.0.0.1:8000/upload-pdf/", {
        method: "POST",
        body: formData,
      });
      if (res.ok) {
        setUploadedFileName(file.name);
        setChatMode("pdf");
        setMessages((prev) => [
          ...prev, 
          { role: "bot", content: `✨ **System Update:** Context loaded from **${file.name}**. I am now optimized for document-specific analysis.` }
        ]);
      }
    } catch (error) {
      console.error(error);
    } finally {
      setIsUploading(false);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMessage = input;
    setInput("");
    setMessages((prev) => [...prev, { role: "user", content: userMessage }]);
    setIsLoading(true);

    const formData = new FormData();
    formData.append("question", userMessage);

    const endpoint = chatMode === "pdf" && uploadedFileName
        ? "http://127.0.0.1:8000/ask-question/"
        : "http://127.0.0.1:8000/ask-simple/";

    try {
      const res = await fetch(endpoint, { method: "POST", body: formData });
      const data = await res.json();
      if (res.ok) setMessages((prev) => [...prev, { role: "bot", content: data.answer }]);
    } catch (error) {
      setMessages((prev) => [...prev, { role: "bot", content: "⚠️ Connectivity Error." }]);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#fafafa] text-slate-900 font-sans selection:bg-emerald-100 overflow-hidden">
      
      {/* 🚀 GLOWING TOP ACCENT BAR */}
      <div className="absolute top-0 left-0 w-full h-[3px] bg-gradient-to-r from-emerald-400 via-emerald-500 to-teal-400 z-50"></div>

      {/* 🌑 MINIMALIST DARK SIDEBAR */}
      <div className="w-[280px] bg-[#0f172a] text-slate-400 flex flex-col shadow-2xl z-20">
        <div className="p-8 pb-10 flex items-center gap-3">
          <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center text-white shadow-[0_0_20px_rgba(16,185,129,0.4)]">
            <Leaf size={22} strokeWidth={2.5} />
          </div>
          <div>
            <h1 className="text-xl font-bold text-white tracking-tight">EcoBot</h1>
            <div className="flex items-center gap-1.5">
              <span className="w-1.5 h-1.5 rounded-full bg-emerald-400 animate-pulse"></span>
              <span className="text-[10px] uppercase tracking-widest font-bold text-emerald-400/80">Active Engine</span>
            </div>
          </div>
        </div>

        <nav className="flex-1 px-4 space-y-1.5">
          <p className="text-[10px] font-black text-slate-600 uppercase tracking-[0.2em] mb-4 px-4">Navigation</p>
          
          <button onClick={() => setChatMode("simple")} className={`group w-full p-3.5 rounded-2xl flex items-center gap-3 transition-all ${chatMode === "simple" ? "bg-white/10 text-white shadow-inner" : "hover:bg-white/5 hover:text-slate-200"}`}>
            <LayoutDashboard size={18} className={chatMode === "simple" ? "text-emerald-400" : "text-slate-500 group-hover:text-slate-300"} />
            <span className="text-sm font-semibold">Discovery Chat</span>
          </button>

          <button onClick={() => uploadedFileName && setChatMode("pdf")} className={`group w-full p-3.5 rounded-2xl flex items-center gap-3 transition-all ${!uploadedFileName ? "opacity-30 cursor-not-allowed" : chatMode === "pdf" ? "bg-white/10 text-white shadow-inner" : "hover:bg-white/5 hover:text-slate-200"}`}>
            <FileText size={18} className={chatMode === "pdf" ? "text-emerald-400" : "text-slate-500 group-hover:text-slate-300"} />
            <span className="text-sm font-semibold">Doc Intelligence</span>
          </button>
        </nav>

        {/* 📥 SEXY UPLOAD AREA */}
        <div className="p-6 mt-auto">
          <div className={`p-6 rounded-[2rem] border-2 border-dashed transition-all duration-500 ${uploadedFileName ? "bg-emerald-500/10 border-emerald-500/40" : "bg-slate-800/40 border-slate-700 hover:border-slate-500"}`}>
            <label className="cursor-pointer flex flex-col items-center text-center group">
              {uploadedFileName ? (
                <CheckCircle2 size={32} className="text-emerald-400 mb-2 drop-shadow-[0_0_8px_rgba(52,211,153,0.5)]" />
              ) : (
                <UploadCloud size={32} className="text-slate-500 mb-2 group-hover:text-emerald-400 transition-colors" />
              )}
              <p className="text-xs font-bold text-slate-300 truncate w-full mb-1">{uploadedFileName || "Upload PDF"}</p>
              <p className="text-[10px] text-slate-500 font-medium">Sustainability Report</p>
              <input type="file" accept=".pdf" className="hidden" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </div>

      {/* ⚪ THE CHAT CANVAS */}
      <div className="flex-1 flex flex-col relative bg-white">
        
        {/* Transparent Header */}
        <header className="h-20 flex items-center justify-between px-10 bg-white/80 backdrop-blur-xl border-b border-slate-100 z-10">
          <div className="flex items-center gap-4">
            <h2 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
              <Sparkles size={16} className="text-emerald-500" />
              {chatMode === "simple" ? "General Protocol" : "Deep Analysis Mode"}
            </h2>
          </div>
          <div className="flex items-center gap-2">
             <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 hover:bg-emerald-50 hover:text-emerald-600 transition-all cursor-pointer">
                <Settings size={16}/>
             </div>
             <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-500 hover:bg-emerald-50 hover:text-emerald-600 transition-all cursor-pointer">
                <HelpCircle size={16}/>
             </div>
          </div>
        </header>

        {/* Message List */}
        <main className="flex-1 overflow-y-auto px-6 py-10 space-y-10 scroll-smooth pb-48">
          <div className="max-w-4xl mx-auto space-y-10">
            {messages.length === 0 ? (
              <div className="h-[50vh] flex flex-col items-center justify-center text-center animate-in fade-in slide-in-from-bottom-4 duration-1000">
                <div className="w-24 h-24 bg-emerald-50 rounded-[2.5rem] flex items-center justify-center mb-6 shadow-xl shadow-emerald-500/5">
                  <Bot size={44} className="text-emerald-500" strokeWidth={1.5} />
                </div>
                <h1 className="text-4xl font-black text-slate-900 mb-3 tracking-tighter">I'm EcoBot.</h1>
                <p className="text-slate-400 text-lg max-w-sm font-medium leading-relaxed">Your professional ESG and Carbon Intelligence partner.</p>
              </div>
            ) : (
              messages.map((msg, idx) => (
                <div key={idx} className={`flex gap-6 ${msg.role === "user" ? "flex-row-reverse" : "flex-row"}`}>
                  <div className={`w-10 h-10 rounded-2xl flex items-center justify-center flex-shrink-0 shadow-sm transition-transform hover:scale-110 ${msg.role === "user" ? "bg-slate-900 text-white" : "bg-emerald-500 text-white shadow-emerald-200"}`}>
                    {msg.role === "user" ? <User size={18} /> : <Bot size={20} />}
                  </div>
                  <div className={`relative max-w-[75%] px-7 py-5 rounded-[2rem] text-[15px] leading-relaxed tracking-wide shadow-sm transition-all ${
                    msg.role === "user" 
                      ? "bg-slate-900 text-slate-100 rounded-tr-none" 
                      : "bg-white text-slate-700 border border-slate-100 rounded-tl-none ring-4 ring-slate-50/50 whitespace-pre-wrap"
                  }`}>
                    {msg.content}
                  </div>
                </div>
              ))
            )}
            {isLoading && (
              <div className="flex gap-6 items-center">
                <div className="w-10 h-10 rounded-2xl bg-emerald-500 flex items-center justify-center text-white shadow-lg animate-pulse">
                  <Bot size={20} />
                </div>
                <div className="flex gap-1.5 items-center">
                  <div className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce [animation-delay:-0.3s]"></div>
                  <div className="w-2 h-2 bg-emerald-400 rounded-full animate-bounce [animation-delay:-0.15s]"></div>
                  <div className="w-2 h-2 bg-emerald-500 rounded-full animate-bounce"></div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>
        </main>

        {/* ⌨️ THE SEXY FLOATING INPUT DECK */}
        <div className="absolute bottom-8 left-0 w-full px-10 pointer-events-none">
          <div className="max-w-4xl mx-auto w-full pointer-events-auto">
            <div className="bg-white/70 backdrop-blur-2xl border border-white p-3 rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.08)] ring-1 ring-slate-200/50">
              <form onSubmit={handleSendMessage} className="flex items-center gap-3">
                <input
                  type="text"
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder={chatMode === "simple" ? "Type a message..." : "Ask the document..."}
                  className="flex-1 bg-slate-50/50 border-none rounded-full py-4 px-8 text-slate-800 placeholder-slate-400 focus:outline-none focus:ring-2 focus:ring-emerald-500/10 transition-all text-base"
                />
                <button
                  type="submit"
                  disabled={isLoading || !input.trim()}
                  className="bg-emerald-500 text-white p-4 rounded-full hover:bg-emerald-600 hover:scale-105 active:scale-95 transition-all shadow-lg shadow-emerald-500/20 flex items-center justify-center disabled:opacity-20"
                >
                  {isLoading ? <Loader2 className="animate-spin" size={24} /> : <Send size={24} />}
                </button>
              </form>
            </div>
            <p className="text-center text-[10px] text-slate-400 mt-4 font-bold uppercase tracking-[0.2em] opacity-50">
              EcoBot Neural Core v2.0 • 2026 Edition
            </p>
          </div>
        </div>

      </div>
    </div>
  );
}